import sys
import heapq
from art import *

def input_check(message):
    while True:
        try:
            user_input = int(input(message))
            if user_input <= 0:
                print(""Error: Please enter a positive integer."")
                continue
            return user_input
        except ValueError:
            print(""Error: Please enter an integer value."")

def find_largest(arr, use_sort=True):
    if use_sort:
        heapq.heapify(arr)
        return heapq.heappop()
    else:
        max_val = arr[0]
        for num in arr[1:]:
            if num > max_val:
                max_val = num
        return max_val

