import sys
import numpy as np

def add(x, y):
    return x + y

def subtract(x, y):
    return x - y

def multiply(x, y):
    return x * y

def divide(x, y):
    if y == 0:
        raise ValueError(""Division by zero is not allowed."")
    return x / y

operators = {
    '+': add,
    '-': subtract,
    '*': multiply,
    '/': divide,
}

def main():
    if len(sys.argv) != 4:
        print(""Usage: python calculator.py [number1] [operator] [number2]"")
        sys.exit()

    number1 = float(sys.argv[1])
    operator_symbol = sys.argv[2]
    number2 = float(sys.argv[3])

    result = operators[operator_symbol](number1, number2)
    print(f""Result: {result}"")

if __name__ == ""__main__"":
    main()
