```python
import string
import random
def generate_password(length, complexity):
    charset = string.ascii_letters + string.digits + string.punctuation
    if complexity == 'simple':
        return ''.join(random.choice(charset) for _ in range(length))
    elif complexity == 'medium':
        return ''.join(random.choice(charset) for _ in range(length // 3)) + \
               ''.join(random.choice(string.ascii_lowercase) for _ in range(length // 4)) + \
               ''.join(random.choice(string.ascii_uppercase) for _ in range(length // 8))
    elif complexity == 'strong':
        return ''.join(random.choice(charset) for _ in range(length // 5)) + \
               ''.join(random.choice(string.ascii_lowercase) for _ in range(length // 6)) + \
               ''.join(random.choice(string.ascii_uppercase) for _ in range(length // 10))
password_strength = {'simple': 1, 'medium': 2, 'strong': 3}
