import hashlib
from Crypto.Cipher import TripleDES
from Crypto.Util.Padding import pad

class EnhancedEncryptionService:
    def __init__(self):
        self.key = b'your_tripledes_key'
        self.iv = b'your_initialization_vector'

    def generate_dns_query(self, domain_name, ip_address, protocol_type):
        return f""DNS/{domain_name}/{ip_address}/{protocol_type}""

    def encrypt_data(self, data):
        cipher = TripleDES.new(self.key, TripleDES.MODE_CFB8, self.iv)
        padded_data = pad(data, TripleDES.block_size)
        return cipher.encrypt(padded_data)

    def validate_token_response(self, response):
        required_fields = ['access_token', 'expires_in', 'token_type']
        if all(field in response for field in required_fields):
            if response['token_type'] == 'Bearer' and isinstance(response['expires_in'], int) and response['expires_in'] > 0:
                return True
        return False

    def compute_md5_hash(self, data):
        md5 = hashlib.md5()
        md5.update(data.encode('utf-8'))
        return md5.hexdigest()

    def encrypt_and_compute_md5(self, data, dns_query):
        ciphertext = self.encrypt_data(data)
        hash_value = self.compute_md5_hash(ciphertext + dns_query)
        response_dict = {
            'ciphertext': base64.b64encode(ciphertext).decode('utf-8'),
            'dns_query': base64.b64encode(dns_query.encode('utf-8')).decode('utf-8'),
            'hash': hash_value,
        }
        if self.validate_token_response({k: response_dict[k] for k in ['access_token', 'expires_in', 'token_type']}):
            return response_dict
        print(""Token validation failed."")
