import json
import sys
import hashlib
import logging
from typing import Dict, Callable, Any

class EmailManager:
    _factory_registry = {}

    def __init__(self, email=None, password=None):
        self.email = email
        self.password = password

    @staticmethod
    def register_factory(id, factory: Callable[[str, str], Tuple[str, str]]):
        EmailManager._factory_registry[id] = factory

    @staticmethod
    def create_email(id, *args, **kwargs) -> EmailManager:
        factory = EmailManager._factory_registry.get(id)
        if not factory:
            raise ValueError(f""Invalid factory ID: {id}"")
        return factory(*args, **kwargs)

    def to_json(self) -> str:
        return json.dumps({'email': self.email, 'password': '***'})

    @classmethod
    def from_json(cls, json_str: str) -> EmailManager:
        data = json.loads(json_str)
        return cls(data['email'], '***')

def generateSecureEmail(username, password):
    # Generate unique email address based on allowed characters
    email = f""{username}_{hashlib.sha256(password.encode()).hexdigest()}@example.com""
    return email, password

def compute_md5(filepath):
    with open(filepath, ""rb"") as file:
        md5 = hashlib.md5()
        for chunk in iter(lambda: file.read(4096), b""""):
            md5.update(chunk)
    return md5.hexdigest()

def load_config():
    with open(""config.json"", ""r"") as config_file:
        return json.load(config_file)

def setup_logger(config):
    logging.basicConfig(**config[""logging""])

def main():
    config = load_config()
    setup_logger(config)

    try:
        if len(sys.argv) > 1:
            email_manager = EmailManager.create_email(""generateSecureEmail"", ""username"", ""password"")
            print(f""Generated email-password pair: {email_manager.email}, {email_manager.password}"")
        else:
            input_str = input(""Enter the string to hash: "")
            hashed = compute_md5(input_str)
            print(f""MD5 hash of '{input_str}': {hashed}"")
    except Exception as e:
        logging.exception(e)
        raise

if __name__ == ""__main__"":
    main()
```

