   def generate_dns_query_with_conditions(num_queries):
       dns_queries_with_conditions = []

       for _ in range(num_queries):
           ip_address = random_ip()
           protocol_type = random_protocol()
           age_threshold_passed = is_transaction_recent(datetime.timedelta(seconds=random.randint(0, TRANSACTION_AGE_THRESHOLD.total_seconds())))
           domain_name = valid_domain_name() + str(random.randint(0, 100))

           transaction = {'protocol_type': protocol_type, 'ip_address': ip_address}

           dns_query = (domain_name, ip_address, protocol_type)

           if age_threshold_passed:
               dns_queries_with_conditions.append((dns_query, transaction))

       return dns_queries_with_conditions

   def random_ip():
       ip = [random.randint(*range) for range in IP_RANGE]
       return '.'.join(map(str, ip))

   def random_protocol():
       return random.choice(PROTOCOLS)

   def valid_domain_name():
       # Simplified logic for generating a valid domain name
       domain_parts = ['example', 'com']
       return '.'.join(domain_parts)

   def is_transaction_recent(transaction_age):
       current_time = datetime.datetime.now()
       return current_time - transaction_age <= TRANSACTION_AGE_THRESHOLD
