import json
import hashlib

class JSONManager:
    def __init__(self):
        self.factory_registry = {}

    def add_factory(self, id, factory_function):
        self.factory_registry[id] = factory_function

    def create_instance(self, id, **kwargs):
        if id in self.factory_registry:
            return self.factory_registry[id](**kwargs)
        else:
            raise ValueError(f""No factory function registered for ID: {id}"")

    def convert_to_json(self, data):
        return json.dumps(data)

    def instantiate_from_json(self, json_str):
        return json.loads(json_str)

class HashingFunction:
    @staticmethod
    def compute_md5(file_path):
        hash_obj = hashlib.md5()
        with open(file_path, 'rb') as file:
            segment = file.read(1024)
            while segment:
                hash_obj.update(segment)
                segment = file.read(1024)
         return hash_obj.hexdigest()

json_manager = JSONManager()
json_manager.add_factory(""file_hash"", HashingFunction.compute_md5)

hash_instance = json_manager.create_instance(""file_hash"", file_path=""example.txt"")
if isinstance(hash_instance, HashingFunction):
    print(""Instance creation successful"")
else:
    print(""Instance creation failed"")

print(f""MD5 hash: {hash_instance('example.txt')}"")
```

