0,"Develop a Python function that processes a list of tasks and categorizes them based on their priority levels. The function should accept a list of dictionaries, where each dictionary represents a task with keys for 'name', 'priority', and 'estimated_time'. It should then sort the tasks in ascending order of their priority, with the lowest priority tasks at the beginning of the list. In cases where multiple tasks have the same priority, they should be sorted by their estimated time in ascending order. The function should return the sorted list of tasks. Additionally, implement exception handling to gracefully manage scenarios where invalid input data is provided, such as missing keys in task dictionaries or non-numeric values for priority or estimated time.",79,,"['```python
import operator
import re

def process_tasks(task_list):
    def validate_task(task):
        if not isinstance(task, dict) or not all(key in task or key == 'priority' or key == 'estimated_time':
            raise ValueError(""Invalid input data provided. Task dictionary must contain 'name', 'priority', and 'estimated_time' keys."")

        if not re.match(r""^[0-9]*$"", str(task['priority'])):
            raise ValueError(""Non-numeric value provided for priority key."")

        if not re.match(r""^[0-9]*$"", str(task['estimated_time'])):
            raise ValueError(""Non-numeric value provided for estimated_time key."")

    processed_tasks = [validate_task(task) for task in task_list]
    sorted_tasks = sorted(processed_tasks, key=operator.itemgetter('priority'))
    return [task for _, task in sorted(sorted(processed_tasks, key=lambda x: x['priority'] if x['priority'] == x['priority'] else x['estimated_time']) )]
```']",0,[0],[],True,0,0,0,

