1,"Create a Python function that processes a list of sensor readings and determines the average temperature for each unique location. The function should calculate the average temperature over the last 10 minutes for each location and return a dictionary containing the location ID, average temperature, and the total number of readings collected within that time frame.",338,,"['```python
import datetime as dt

def process_sensor_readings(readings):
    data = {}

    for reading in readings:
        location_id = reading['location_id']
        timestamp = dt.datetime.strptime(reading['timestamp'], ""%Y-%m-%d %H:%M:%S"")

        if location_id not in data:
            data[location_id] = {'average_temperature': 0, 'total_readings': 0}

        current_time = dt.datetime.now()
        ten_minutes_ago = current_time - dt.timedelta(minutes=10)

        if timestamp >= (ten_minutes_ago - dt.timedelta(seconds=reading['timestamp'].split("" "")[-1].split("":"")[0])).replace(hour=current_time.hour, minute=current_time.minute):
            data[location_id]['total_readings'] += 1
            data[location_id]['average_temperature'] = (data[location_id]['average_temperature'] * data[location_id]['total_readings'] + reading['temperature']) / (data[location_id]['total_readings'] + 1)

    return {key: value for key, value in data.items() if value['total_readings'] >= 1}
```']",52,[0],[],True,0,0,0,

