    def validate_token_response(self, response):
        required_fields = {'access_token', 'expires_in', 'token_type'}
        optional_field = 'refresh_token'

        if not set(response.keys()) <= required_fields:
            return False

        if isinstance(response['access_token'], str) is False:
            return False

        if response['expires_in'] <= 0:
            return False

        if response['token_type'] != ""Bearer"":
            return False

        if optional_field in response and isinstance(response[optional_field], str) is False:
            return False

        return True

    def compute_md5_hash(self, data):
        md5 = hashlib.md5()
        md5.update(data.encode('utf-8'))
        return md5.hexdigest()

    def encrypt_and_compute_md5(self, data, domain, ip):
        query = self.dns_query(domain, ip)
        encrypted_data = self.encrypt_data(data)
        hashed_data = self.compute_md5_hash(encrypted_data + query)
        response_dict = {
            'encoded': base64.b64encode(encrypted_data).decode('utf-8'),
            'md5': hashed_data,
            'query': query
        }
        return response_dict
