import hashlib
import hmac
from cryptography.fernet import Fernet
import base64
import sys

class DataIntegrityService:
    def GenerateSignature(self, data):
        key = hashlib.sha256(b'secret_key').digest()
        return hmac.new(key, msg=data.encode(), digestmod=hashlib.sha256).digest()

    def VerifySignature(self, data, signature):
        key = hashlib.sha256(b'secret_key').digest()
        calculated_signature = hmac.new(key, msg=data.encode(), digestmod=hashlib.sha256).digest()
        return hmac.compare_digest(calculated_signature, signature)

    def EncryptData(self, data):
        key = Fernet.generate_key()
        fernet = Fernet(key)
        return base64.b64encode(fernet.encrypt(data.encode())).decode()

    def IntegrityAndEncryptionCheck(self, data):
        signature = self.GenerateSignature(data)
        encrypted_data = self.EncryptData(data)

        if not self.VerifySignature(data, signature):
            print(""Error: Signature validation failed."")
            sys.exit()

        return encrypted_data
```

