import json
import hashlib
import requests
import os
from typing import Callable

class JSONManager:
    def __init__(self):
        self.factories = {}
        self.registry = []

    def add_factory(self, id, function: Callable):
        self.factories[id] = function
        self.registry.append((id, function))

    def create_instance(self, id, **kwargs):
        for factory_id, factory in self.registry:
            if factory_id == id:
                return factory(**kwargs)
        raise ValueError(f""No factory found for ID '{id}'"")

    def instantiate_from_json(self, json_str):
        obj = json.loads(json_str)
        for factory_id, factory in self.registry:
            try:
                return factory(**obj)
            except Exception as e:
                pass
        raise ValueError(""Unable to instantiate object from provided JSON"")

    def fetch_md5(self, filepath):
        with open(filepath, ""rb"") as f:
            hash_obj = hashlib.md5()
            for chunk in iter(lambda: f.read(8192), b""""):
                hash_obj.update(chunk)
        return hash_obj.hexdigest()

class WeatherAPI(JSONManager):
    def __init__(self):
        super().__init__()
        self.add_factory(""weather"", self.fetch_weather_data)

    def fetch_weather_data(self, api_url, location_id):
        """"""Fetches weather data using an HTTP GET request.""""""
        try:
            response = requests.get(f""{api_url}?id={location_id}"")
            response.raise_for_status()
            return json.loads(response.text)
        except requests.RequestException as e:
            print(f""Error occurred during HTTP request: {e}"")
            return None

def process_weather_data(api_url, location_id):
    manager = WeatherAPI()
    json_str = manager.convert_to_json(manager.fetch_weather_data(api_url, location_id))
    if not json_str:
        return None

    return manager.instantiate_from_json(json_str)

