def caesar_cipher(message, shifts=3):
    result = """"
    for char in message:
        if char.isalpha():
            ascii_offset = ord('a') if char.islower() else ord('A')
            shifted_ascii = (ord(char) + shifts - ascii_offset) % 26 + ascii_offset
            result += chr(shifted_ascii)
        else:
            result += char
    return result
