- Implement error management for edge cases, including correct handling of AM/PM indicators and invalid time inputs.",338,,"['```python
import re

class TimeConverter:
    def __init__(self, time_str):
        self._time_str = self._validate_time(time_str)

    @staticmethod
    def _validate_time(time_str):
        pattern = r""^(\d{1,2}):(\d{2}) (AM|PM)$""
        match = re.match(pattern, time_str)
        if not match:
            raise ValueError(""Invalid time format"")

        hours = int(match.group(1))
        minutes = int(match.group(2))

        if hours < 1 or hours > 12 or (hours == 12 and minutes > 59):
            raise ValueError(""Hour value out of range"")

        return time_str

    def convertTo24Hour(self):
        hour = int(re.match(r""(\d{1,2}):(\d{2}) (AM|PM)"", self._time_str).group(1))
        am_pm = re.match(r""(\d{1,2}):(\d{2}) (AM|PM)"", self._time_str).group(3)

        if am_pm == ""PM"":
            if hour != 12:
                return str(int(hour) + 12)
            else:
                return ""12""
        elif hour not in [12]:
            return f""{hour}""
        else:
            raise ValueError(""Invalid AM/PM indicator"")

    def displayTime(self):
        original = self._time_str
        converted = self.convertTo24Hour()
        return f""Original: {original} | Converted: {converted}""
