import json
import hashlib
import requests

class JSONManager:
    registry = {}

    @staticmethod
    def register(factory):
        JSONManager.registry[factory.__name__] = factory

    @staticmethod
    def from_json(cls, json_string):
        if cls not in JSONManager.registry:
            raise ValueError(f""Unknown class {cls}"")
        return JSONManager.registry[cls](json.loads(json_string))

    @staticmethod
    def to_json(obj):
        return json.dumps(obj.__dict__)

    @staticmethod
    def md5(file_path):
        with open(file_path, ""rb"") as f:
            data = f.read()
            hasher = hashlib.md5()
            hasher.update(data)
            return hasher.hexdigest()

class WeatherAPI:
    def __init__(self):
        JSONManager.register(self.__weather__)

    @staticmethod
    def __weather__(json_string):
        return WeatherAPI._from_json(json_string)

    def _from_json(cls, json_string):
        if cls != WeatherAPI:
            raise ValueError(""Invalid class for deserialization"")
        return cls()

    def fetch_weather_data(self, api_url, location_id):
        try:
            response = requests.get(api_url, params={'id': location_id})
            if not response.ok:
                raise ValueError(""Invalid response or network issue"")
            return response.json()
        except Exception as e:
            print(f""Error fetching weather data: {e}"")
            return None

    def convert_to_json(self, data):
        return JSONManager.to_json(data)

    def process_weather_data(weather_json):
        api = WeatherAPI().fetch_weather_data(""YOUR_API_URL"", ""YOUR_LOCATION_ID"")
        if api:
            weather_obj = JSONManager.from_json(api)
            return weather_obj
        return None

# Usage example
api = WeatherAPI()
weather_data = api.process_weather_data()
if weather_data:
    print(JSONManager.to_json(weather_data))
