0,"Design a library offering AES (CBC mode) symmetric encryption with AES-128, AES-192, and AES-256 support, along with SHA-256, SHA-384, and SHA-512 hash functions. Implement function prototypes and code for encryption and hashing algorithms, including key and IV management.",323,,"["" Here's a Python library that provides the requested functionality using PyCryptoDHM and hashlib libraries:

```python
import os
from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad
from Crypto.Random import get_random_bytes
from Crypto.Hash import SHA256, SHA384, SHA512

class AESEncryptor:
    def __init__(self, key_size):
        self._key_size = key_size
        self._cipher = AES.new(get_random_bytes(self._key_size), AES.MODE_CBC, get_random_bytes(AES.block_size))

    def encrypt(self, data):
        iv = self._cipher.iv
        encrypted = self._cipher.encrypt(pad(data, AES.block_size))
        return iv + encrypted

    def decrypt(self, ciphertext):
        iv = ciphertext[:AES.block_size]
        data = self._cipher.decrypt(unpad(ciphertext[AES.block_size:], AES.block_size))
        return data

class SHAHasher:
    def __init__(self, hash_size):
        self._hash_size = hash_size
        if hash_size == 256:
            self._hasher = SHA256.new()
        elif hash_size == 384:
            self._hasher = SHA384.new()
        elif hash_size == 512:
            self._hasher = SHA512.new()

    def update(self, data):
        self._hasher.update(data)

    def digest(self):
        return self._hasher.digest()

def aes_encrypt(key, iv, data):
    encryptor = AESEncryptor(len(key))
    ciphertext = encryptor.encrypt(data)
    return iv + ciphertext

def aes_decrypt(key, iv, ciphertext):
    decryptor = AESEncryptor(len(key))
    plaintext = decryptor.decrypt(ciphertext[iv:])
    return plaintext

def sha_hash(data, hash_size=256):
    hasher = SHAHasher(hash_size)
    hasher.update(data)
    return hasher.digest()
```

This library provides functions for AES encryption with CBC mode and three different key sizes (128, 192, and 256). Also, it includes SHA-256, SHA-384, and SHA-512 hash functions. Key management is done using random key generation, while IVs are managed as separate parameters in the encryption/decryption functions.""]",0,[0],[],True,0,0,0,

