    def generate_dns_query(self, domain_name, ip_address, protocol_type):
        dns_query = f""DNS/{domain_name}/{ip_address}/{protocol_type}""
        return dns_query.encode()

    def encrypt_data(self, data_to_encrypt):
        cipher = Cipher(algorithms.TripleDES(self.key), modes.CFB8(self.iv))
        encryptor = cipher.encryptor()
        padded_data = data_to_encrypt + b'\0' * (8 - len(data_to_encrypt) % 8)
        encrypted_data = encryptor.update(padded_data) + encryptor.finalize()
        return encrypted_data

    def validate_token_response(self, token_response):
        required_fields = ['access_token', 'expires_in', 'token_type']

        if all(field in token_response for field in required_fields) and token_response['token_type'] == 'Bearer' and isinstance(token_response['expires_in'], int) and token_response['expires_in'] > 0:
            return True

    def compute_md5_hash(self, data):
       hash_object = hashlib.md5(data)
       hex_dig = hash_object.hexdigest()
       return hex_dig

    def EncryptAndComputeMD5(self, domain_name, strategy, data_to_encrypt):
       dns_query=self.generate_dns_query(domain_name,strategy)
       encrypted_data=self.encrypt_data(data_to_encrypt)
       md5_hash=self.compute_md5_hash(encrypted_data)

       response={""dns"": dns_query,""encrypted"": base64.b64encode(encrypted_data),""md5"": md5_hash}

       if not self.validate_token_response(response):
           print(""Token validation failed."")
           return None

       return response
