def caesar_cipher(message, shifts=3):
    result = """"
    alphabet = ""abcdefghijklmnopqrstuvwxyz""
    for char in message:
        if char.isalpha():
            position = ord(char) - 97
            shifted_position = (position + shifts) % 26
            result += alphabet[shifted_position]
        else:
            result += char
    return result.lower()
