def inorder_traversal(level_order):
    if not level_order:
        return None

    root = TreeNode(level_order[0])
    queue = [root]
    i = 1

    while i < len(level_order):
        node = queue.pop(0)
        if node.left is None and node.right is None:
            continue

        if node.left is not None:
            queue.append(node.left)
        if node.right is not None:
            queue.append(node.right)
        queue.append(TreeNode(level_order[i]))
        i += 1

    result = []
    def traverse(node):
        if node:
            traverse(node.left)
            result.append(node.val)
            traverse(node.right)

    traverse(root)
    return result

class TreeNode:
    def __init__(self, x):
        self.val = x
        self.left = None
        self.right = None
