import random
import time
from collections import defaultdict
from typing import Dict, List, Tuple

def generate_api_requests(num_requests: int, rate_limits: Dict[str, float], user_agents: List[str], max_intervals: Dict[str, float]):
    endpoints = list(rate_limits.keys())
    user_agent_choices = user_agents if len(user_agents) >= num_requests else user_agents * (num_requests // len(user_agents)) + [user_agents[-1] *(num_requests % len(user_agents))]

    def get_random_endpoint() -> str:
        return random.choice(endpoints)

    def get_random_user_agent() -> str:
        return random.choice(user_agent_choices)

    def get_random_interval(max_interval: float) -> float:
        return random.uniform(0, max_interval)

    def get_random_recent_calls_count(rate_limit: float) -> int:
        recent_calls = [0] * len(endpoints)  # Mimic previous calls to each endpoint
        threshold = round(random.uniform(0, rate_limit))
        for idx, call in enumerate(recent_calls):
            if call < threshold:
                recent_calls[idx] += 1
        return recent_calls

    def get_compatibility_score() -> float:
        # Implement custom scoring logic based on user agent compatibility and endpoint complexity
        return random.uniform(0, 1)

    requests = []
    for _ in range(num_requests):
        req = {
            'endpoint': get_random_endpoint(),
            'user_agent': get_random_user_agent(),
            'interval': get_random_interval(max_intervals[get_random_endpoint()]),
            'recent_calls_count': get_random_recent_calls_count(rate_limits[get_random_endpoint()]),
            'compatibility_score': get_compatibility_score(),
        }
        requests.append(req)
    return requests
```

