- The average age of active sessions",338,,"['```python
import datetime
from typing import List, Dict

class UserSessionManager:
    def __init__(self):
        self.session_list = []
        self.max_sessions = 5
        self.session_ids = {sid: i for i, sid in enumerate([], self.max_sessions)}

    def create_session(self) -> int:
        if len(self.session_list) < self.max_sessions:
            session_id = next(iter(self.session_ids))
            self.session_list.append((session_id, datetime.datetime.now()))
            del self.session_ids[session_id]
            return session_id
        else:
            return None

    def log_user_in(self, user_id: int) -> int or None:
        session_id = next((sid for sid, _ in self.session_list if sid[0] == user_id), None)
        if not session_id:
            session_id = self.create_session()
        return session_id

    def log_user_out(self, session_id: int):
        for idx, (sid, _) in enumerate(self.session_list):
            if sid == session_id:
                del self.session_list[idx]
                break

    def get_active_users(self) -> List[int]:
        return [sid[0] for sid, _ in self.session_list]

    def calculate_session_age(self, session_id: int) -> float or None:
        for session in self.session_list:
            if session[0] == session_id:
                now = datetime.datetime.now()
                age = (now - session[1]).days
                return age
        return None

# Example usage:
manager = UserSessionManager()
sessions = [manager.create_session() for _ in range(10)]
active_users = set()
for user in sessions:
    uid = manager.log_user_in(user)
    if uid is not None:
        active_users.add(uid)

print(f""Total number of active users: {len(active_users)}"")
average_age = sum([manager.calculate_session_age(uid) for uid in active_users] or [0]) / len(active_users)
print(f""Average age of active sessions: {average_age}"")
