def find_largest_integer(size=None):
    if size is None:
        try:
            size = int(input(""Enter the size of the array (or press Enter to use default): ""))
        except ValueError:
            print(""Invalid input. Using default array size."")
            size = 5

        if size <= 0:
            raise ValueError(""Array size must be a positive integer."")

    arr = []

    print(f""Enter {size} integers separated by spaces:"")

    try:
        numbers = input().split()

        for num in numbers:
            arr.append(validate_input(num))

        arr.sort()
        return arr[-1]

    except Exception as e:
        print(f""Error: {e}"")
        return None

while True:
    try:
        largest_integer = find_largest_integer()

        if largest_integer is not None:
            print(f""The largest integer is: {largest_integer}"")

        continue_programming = input(""Do you want to continue? (yes/no): "").lower()

        if continue_programming != 'yes':
            break

    except KeyboardInterrupt:
        print(""\nExiting program..."")
        break
