10. Adds command-line argument support for input directory paths, output file formats (JSON or CSV), customizable log levels for detailed debugging information, and an option to specify which tags should be considered during parsing.",611,,"['```python
import os
import re
import json
import pandas as pd
from bs4 import BeautifulSoup
from urllib.parse import urljoin
from argparse import ArgumentParser
import requests
from cachetools import TTLCache
import logging

class CustomObject:
    def __init__(self, **kwargs):
        self.__dict__.update(kwargs)

class HTMLScraper:
    CACHE = TTLCache(maxsize=128, ttl=600)

    def __init__(self, log_level='INFO', input_dirs=None, tags_to_parse=None):
        self.log = logging.getLogger(__name__)
        self.log.setLevel(log_level)
        self.input_dirs = input_dirs or []
        self.tags_to_parse = tags_to_parse or []
        self.cache = HTMLScraper.CACHE

    def _find_files(self, directory):
        file_paths = []
        for root, dirs, files in os.walk(directory):
            for file in files:
                if file.lower().endswith(('.html', '.htm')):
                    file_paths.append(os.path.join(root, file))
        return file_paths

    def _parse_file(self, file_path):
        try:
            with open(file_path) as f:
                soup = BeautifulSoup(f, 'html.parser')

            objects = {}
            for tag in self.tags_to_parse:
                tags = soup.find_all(tag)
                tag_objects = [self._parse_tag(t, tag) for t in tags]
                objects[tag] = tag_objects

            return objects
        except Exception as e:
            self.log.error(f""Error while parsing {file_path}: {e}"")
            raise e

    def _parse_tag(self, tag, parent_tag):
        attrs = {}
        for name, value in tag.attrs.items():
            if re.match(r'^data-[a-zA-Z0-9_-]*$', name):
                attrs[name.replace('data-', '').lower()] = value

        content = tag.get_text() or ''
        return CustomObject(**attrs, **{'content': content, 'parent_tag': parent_tag})

    def _extract_attributes(self, objects, attributes):
        results = {}
        for tag, obj in objects.items():
            for attr in attributes:
                if attr not in obj[0]:
                    continue
                value = obj[0][attr]
                if tag not in results:
                    results[tag] = []
                results[tag].append(value)
        return results

    def scrape(self):
        all_files = []
        for dir in self.input_dirs:
            all_files += self._find_files(dir)

        data = {}
        for file_path in all_files:
            objects = self._parse_file(file_path)
            data[os.path.basename(file_path)] = objects

        attributes = ['data-custom1', 'data-custom2']
        results = self._extract_attributes(data, attributes)
        return results

    def save(self, results, output_format='json'):
        if output_format == 'json':
            with open('output.json', 'w') as outfile:
                json.dump(results, outfile)
        elif output_format == 'csv':
            df = pd.DataFrame(list(results.items()))
            df.to_csv('output.csv')

if __name__ == '__main__':
    parser = ArgumentParser()
    parser.add_argument('--input-dirs', nargs='+', default=['./inputs/html'])
    parser.add_argument('--output-format', choices=('json', 'csv'), default='json')
    parser.add_argument('--log-level', choices=('DEBUG', 'INFO', 'WARNING', 'ERROR', 'CRITICAL'))
    parser.add_argument('--tags-to-parse', nargs='*', default=['div', 'span'])
    args = parser.parse_args()

    scraper = HTMLScraper(args.log_level, args.input_dirs, args.tags_to_parse)
    results = scraper.scrape()
    scraper.save(results, args.output_format)
```

You can run the script by executing `python html_scraper.py --input-dirs ./inputs/html1 ./inputs/html2` where `./inputs/html1` and `./inputs/html2` are directories containing your HTML files. Adjust the input directories and other arguments as needed, and make sure to install `beautifulsoup4`, `lxml`, and `cachetools` libraries before running the script.

For unit testing, you can create a separate module with test cases for different edge cases.']",0,[0],[],True,0,0,0,

