0,"Create a simplified Python Django web app middleware to track user activity, including page views, form submissions, and API calls. Focus on seamless integration into the existing Django project without impacting performance.",521,,"[""```python
from django.utils.logging import get_logger
import json

class UserActivityMiddleware:
    def __init__(self, get_response):
        self.get_response = get_response
        self.logger = get_logger('user_activity')

    def __call__(self, request):
        request.user_activity = {'page': request.path, 'timestamp': str(request.time)}

        response = self.get_response(request)

        if hasattr(request, 'POST'):
            form_data = json.dumps(request.POST.dict())
            request.user_activity['form'] = {'data': form_data, 'timestamp': str(request.time)}

        if hasattr(request, 'META':
            api_call = request.META.get('HTTP_X_API_CALL', None)
            if api_call:
                request.user_activity['api'] = {'url': api_call, 'timestamp': str(request.time)}

        return response
```

To utilize this middleware in your Django project, you can add it to the `MIDDLEWARE` setting in your project's settings file:

```python
MIDDLEWARE = [
    # ... Other middlewares
    'your_app.middleware.UserActivityMiddleware',
]
