import requests
import json
from requests.exceptions import RequestException, ConnectionError, Timeout, TooManyRedirects

def api_post(url, payload):
    try:
        response = requests.post(url, json=payload, timeout=(10, 15))
        if response.status_code in (200, 201):
            return json.loads(response.content)
        elif response.status_code == 400:
            # Handle specific 400 error here
            raise Exception(""Bad Request"")
        elif response.status_code == 401:
            # Handle specific 401 error here
            raise Exception(""Unauthorized"")
        elif response.status_code == 403:
            # Handle specific 403 error here
            raise Exception(""Forbidden"")
        elif response.status_code == 404:
            # Handle specific 404 error here
            raise Exception(""Not Found"")
        elif response.status_code == 500:
            # Handle specific 500 error here
            raise Exception(""Internal Server Error"")
        else:
            raise Exception(f""Unexpected error occurred ({response.status_code})"")
    except (RequestException, ConnectionError, Timeout, TooManyRedirects) as e:
        if isinstance(e, RequestException):
            print(f""Request exception: {e}"")
        elif isinstance(e, ConnectionError):
            print(""Connection error occurred."")
        elif isinstance(e, Timeout):
            print(""Timeout error occurred."")
        elif isinstance(e, TooManyRedirects):
            print(""Too many redirects error occurred."")
        raise Exception(f""API request failed: {e}"")
