def replace_placeholders(config, placeholders_dict):
    with open(config) as f:
        lines = [line for line in f]

    new_lines = []
    for line in lines:
        for placeholder, value in placeholders_dict.items():
            if placeholder in line:
                new_lines.append(line.replace(placeholder, value))
                break
        else:
            new_lines.append(line)

    return new_lines

def add_password_line(config, encrypted_password):
    lines = [line for line in open(config)]
    lines.append(f""PLACEHOLDER_PASSWORD={encrypted_password}"")
    with open(config, 'w') as f:
        for line in lines:
            f.write(line)

def main():
    if len(sys.argv) != 4:
        print(""Usage: python script.py config_file placeholders_dict encrypted_password"")
