def create_jwt(secret, user, expiry):
    payload = {
        'iss': 'your-issuer',  # Your issuer identifier
        'exp': int(datetime.datetime.utcnow().timestamp()) + expiry,
        'user': user
    }
    headers = {'alg': 'RS256', 'kid': 'your_key_identifier'}
    token = jwt.encode(payload, secret, headers=headers)
    return token

# Validate JWT using the provided secret key and JSON schema validation
def validate_jwt(secret, token):
    try:
        payload = jwt.decode(token, secret, algorithms=['RS256'])
    except Exception as e:
        return {'error': str(e)}, 401

    if not jsonschema.validate(payload, {
            'type': 'object',
            'properties': {
                'iss': {'type': 'string'},
                'exp': {'type': 'number'},
                'user': {'type': 'string'}
            },
            'required': ['iss', 'exp', 'user']}):
        return {'error': 'Invalid JSON structure'}, 401

    now = datetime.datetime.utcnow()
    if payload['exp'] <= now:
        return {'error': 'Token expired'}, 403

    return token, True

# Generate a secure hash for session IDs using HMAC-SHA256
def generate_secure_hash(session_id):
    key = base64.b64decode(os.environ['JWT_SECRET'])
    hash_object = hmac.new(key, session_id.encode(), hashlib.sha256)
    return hash_object.digest()

# Generate and set secure session cookie on successful authentication
def create_session_cookie(res, session_id):
    # Set secure and HttpOnly flags for the session cookie here
    res.set_cookie('session', session_id, expires=datetime.timedelta(days=1).total_seconds())
