import hashlib
from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad
from Crypto.Random import get_random_bytes

class AESEncryption:
    def __init__(self, key_size):
        self.key_size = key_size
        self.keys = self._generate_keys()

    @staticmethod
    def _generate_keys():
        keys = []
        for size in (128, 192, 256):
            keys.append(get_random_bytes(AES.newkey_size(size)))
        return keys

    def encrypt(self, message, iv=None):
        if not iv:
            iv = get_random_bytes(AES.block_size)
        cipher = AES.new(self.keys[self.key_size], AES.MODE_CBC, iv)
        return iv + cipher.encrypt(pad(message, AES.block_size))

    def decrypt(self, encrypted_message, iv):
        cipher = AES.new(self.keys[self.key_size], AES.MODE_CBC, iv)
        return unpad(encrypted_message[-AES.block_size:], AES.block_size)[iv:]

class HashFunction:
    def sha256(self, message):
        return hashlib.sha256(message).digest()

    def sha384(self, message):
        return hashlib.sha384(message).digest()

    def sha512(self, message):
        return hashlib.sha512(message).digest()
