import datetime
from typing import List, Dict

class UserSessionManager:
    def __init__(self):
        self.session_list = []
        self.max_sessions = 5
        self.current_ids = set()

    def create_session(self) -> int:
        session_id = next((i for i in range(1, max(self.current_ids) + 2) if i not in self.current_ids), 1)
        self.current_ids.add(session_id)
        self.session_list.append({'user_id': None, 'timestamp': datetime.datetime.now()})
        return session_id

    def log_user_in(self, user_id: int, session_id: int = None) -> int or None:
        if not session_id:
            session_id = self.create_session()
        for index, session in enumerate(self.session_list):
            if session['user_id'] is None:
                session['user_id'] = user_id
                self.session_list[index]['timestamp'] = datetime.datetime.now()
                return session_id
        return None

    def log_user_out(self, session_id: int) -> bool:
        for index, session in enumerate(self.session_list):
            if session['session_id'] == session_id:
                self.session_list[index]['user_id'] = None
                del self.current_ids[session['session_id'] - 1]
                return True
        return False

    def get_active_users(self) -> List[int]:
        active_users = []
        for session in self.session_list:
            if session['user_id'] is not None:
                active_users.append(session['user_id'])
        return active_users

    def calculate_session_age(self, session_id: int) -> int or None:
        for session in self.session_list:
            if session['session_id'] == session_id:
                delta = datetime.datetime.now() - session['timestamp']
                return delta.days
        return None
