import sqlite3
import psycopg2 # For PostgreSQL support
from datetime import datetime, timedelta

def update_database(db_type, db_url, db_id, **kwargs):
    conn = None
    try:
        if db_type == ""sqlite"":
            conn = sqlite3.connect(db_url)
            c = conn.cursor()
        elif db_type == ""postgresql"":
            conn = psycopg2.connect(db_url)
            c = conn.cursor()

        query = f""UPDATE records SET {', '.join(f'{k}={sqlite3.paramstyle.python}?' for k in kwargs)} WHERE id={db_id}""
        c.execute(query, kwargs)
        conn.commit()
    except Exception as e:
        print(""Error:"", e)
    finally:
        if conn:
            conn.close()
```

