    def register_factory(name, factory):
        JSONManager_functions().add_factory(name, factory)

    @staticmethod
    def get_factory(name):
        return JSONManager_functions().create_instance(name)

def command_with_hash(command):
    process = subprocess.run(command, capture_output=True, text=True, errors=""ignore"")
    if process.returncode != 0:
        raise Exception(""Command encountered an error."")

    output = process.stdout + process.stderr
    md5 = hashlib.md5(output.encode()).hexdigest()
    return (output, md5)

