import random
import string

class Factory:
    def __init__(self, id, create_func):
        self.id = id
        self.create_func = create_func

class CustomStringManager:
    def __init__(self):
        self.factories = {}

    def add_factory(self, id, create_func):
        self.factories[id] = Factory(id, create_func)

    def generate_random_string(length=10):
        return ''.join(random.choice(string.ascii_letters + string.digits) for _ in range(length))

    def create_instance(self, factory_id, length=None):
        factory = self.factories[factory_id]
        if length is None:
            length = 10
        return factory.create_func(length)
