import sqlite3
import hashlib
from Crypto.Cipher import AES
from Crypto.Random import get_random_bytes
from Crypto.Util.Padding import pad, unpad

def generateKey():
    return get_random_bytes(32)

def encryptData(key: bytes, data: bytes):
    cipher = AES.new(key, AES.MODE_CBC, b'this-is-a-password')
    return cipher.encrypt(pad(data, AES.block_size))

def decryptData(key: bytes, encryptedData):
    cipher = AES.new(key, AES.MODE_CBC, b'this-is-a-password')
    return unpad(cipher.decrypt(encryptedData), AES.block_size)

def hashPassword(password):
    return hashlib.sha256(password.encode()).hexdigest()

def executeQuery(query, args=None):
