class CryptoHasher:
    def __init__(self):
        self.algorithms = {
            ""SHA-256"": hashlib.sha256,
            ""SHA-384"": hashlib.sha384,
            ""SHA-512"": hashlib.sha512,
            ""RIPEMD-160"": hashlib.new(""ripemd160"")
        }
        self.encryption = bcrypt

    def compute_hash(self, input_string: str, algorithm_name: str) -> str:
        if algorithm_name not in self.algorithms:
            raise ValueError(""Unsupported hashing algorithm"")

        hasher = self.algorithms[algorithm_name]
        hash_object = hasher(input_string.encode('utf-8'))
        return base64.b64encode(hash_object.digest()).decode('utf-8')

    def generate_encrypted_password(self, password: str) -> str:
        salt = self.encryption.gensalt()
        hashed_password = self.encryption.hashpw(password.encode('utf-8'), salt)
        return hashed_password + "":"" + salt.decode(""utf-8"")

