def remove_duplicates(s):
    return list(set(map(int, s.split(','))) if s else [])

def product_of_even_numbers(lst):
    return reduce(lambda x, y: x * y, filter(lambda n: n % 2 == 0, lst)) if lst else None

def main():
    test_cases = [
        '1,2,3,4,5,6,7,8,9,1,2',
        ""3,3,2,4,5,6,7,2,3"",
        ',5,3,2,6,1,,9',
        '10,20,30,40,50'
    ]

    for test_case in test_cases:
        unique_sorted = remove_duplicates(test_case)
        print(f""Input: {test_case}, Unique sorted numbers: {unique_sorted}"")
        even_product = product_of_even_numbers([int(n) for n in test_case.split(',') if n])
        if even_product is not None:
            print(f""Product of all even numbers: {even_product}"")
        else:
            print(""Error: Non-integer input detected."")

