from datetime import timedelta, datetime

class UserSessionManager:
    def __init__(self):
        self.session_list = []
        self.max_sessions = 5
        self.next_id = 1

    def create_session(self):
        session = {""user_id"": None, ""session_id"": self.next_id, ""initiated_at"": datetime.now()}
        self.session_list.append(session)
        self.next_id += 1
        return session[""session_id""]

    def log_user_in(self, user_id, session_id):
        for index, session in enumerate(self.session_list):
            if session[""user_id""] is None and session[""session_id""] == session_id:
                self.session_list[index][""user_id""] = user_id
                return session_id
        return None

    def log_user_out(self, session_id):
        for index, session in enumerate(self.session_list):
            if session[""session_id""] == session_id:
                self.session_list[index][""user_id""] = None
                del self.session_list[index]
                return True
        return False

    def get_active_users(self):
        active_users = [session[""user_id""] for session in self.session_list if session[""user_id""] is not None]
        return active_users

    def calculate_session_age(self, session_id):
        for session in self.session_list:
            if session[""session_id""] == session_id:
                delta = datetime.now() - session[""initiated_at""]
                return round(delta.total_seconds() / (60 * 60 * 24))

