from binascii import unhexlify, hexlify

def make_mac():
    return ':'.join([hexlify(os.urandom(3)).decode() for _ in range(6)])

def make_ip():
    return str(IPv4Address(int(random.uniform(10_000_001, 10_000_254))))

protocols = ['TCP', 'UDP', 'ICMP', 'ARP']

def create_packet():
    mac = make_mac()
    ip = make_ip()
    protocol = random.choice(protocols)
    return {'MAC': mac, 'IP': ip, 'Protocol': protocol}

def create_packets(num=100):
    packets = []
    for _ in range(num):
        packet = create_packet()
        packets.append(packet)
    return packets
