import logging
import hashlib
import os

class PasswordEncryptionException(Exception):
    pass

class CustomEncryptionException(PasswordEncryptionException):
    pass

class EncryptionAlgorithm:
    def __init__(self, name, algorithm_type):
        self.name = name
        self.algorithm_type = algorithm_type

    def encrypt(self, password):
        raise NotImplementedError(""Subclasses must implement this method"")

class CustomEncryptionFactory:
    registered_encryption = {}

    @staticmethod
    def register_encryption(name, encryption_algorithm):
        if name in CustomEncryptionFactory.registered_encryption:
            raise ValueError(f""Encryption algorithm {name} already registered"")
        CustomEncryptionFactory.registered_encryption[name] = encryption_algorithm

    @staticmethod
    def get_registered_encryptions():
        return CustomEncryptionFactory.registered_encryption.keys()

class HashingAlgorithm(EncryptionAlgorithm):
    def __init__(self, name, algorithm_type, salt_length=16):
        super().__init__(name, algorithm_type)
        self.salt_length = salt_length

    def encrypt(self, password):
        salt = os.urandom(self.salt_length)
        hashed_password = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return salt + hashed_password

class PasswordStorage:
    max_size = 10

    def __init__(self):
        self.cache = {}

    def store_password(self, encrypted_password):
        if len(self.cache) >= PasswordStorage.max_size:
            raise ValueError(""Password cache is full"")

        key_prefixes = [key for key in self.cache.keys() if key.startswith(""encrypted_"")]

        if not key_prefixes:
            new_key = ""encrypted_""
            while new_key in self.cache:
                new_key += ""_""
            encrypted_password.key = new_key + hashlib.sha256(encrypted_password.encrypted_password).hexdigest()

            self.cache[encrypted_password.key] = encrypted_password

            logging.info(f""Stored encrypted password: {encrypted_password.key}"")

            return True

    def store_encrypted_password(password_storage, encrypted_data):
        passwd = EncryptedPassword(encrypted_data['password'], encrypted_data['salt'])
        return password_storage.store_password(passwd)

    def get_encrypted_password(password_storage) -> str | None:
        for key in password_storage.cache.keys():
            if key.startswith(""encrypted_""):
                encrypted_password = password_storage.cache[key]
                return encrypted_password.encrypted_password
        return None

class EncryptedPassword:
    def __init__(self, password, salt):
        self.encrypted_password = password
        self.salt = salt

class PasswordManager:
    @staticmethod
    def register_encryption(name, encryption_algorithm):
        return CustomEncryptionFactory.register_encryption(name, encryption_algorithm)

def main():
    CustomEncryptionFactory.register_encryption(""hashing"", HashingAlgorithm(""hashing"", ""hash""))

if __name__ == ""__main__"":
