 def calculate_session_age(self, session_ids=None):
     from datetime import datetime, timedelta

     current_time = datetime.now()

     creation_times_dict = {session: datetime(2023, 1, 1) + timedelta(days=i-1) for i, session in enumerate(self.session_list)}

     result_age_days = []
