```python
from flask import Flask, request

app = Flask(__name__)

class ResourceModel:
    def __init__(self):
        self.data = {}

@app.route('/update', methods=['POST'])
def update_resource():
    resource_id = int(request.json['resource_id'])
    updated_data = request.json['updated_data']

    if resource_id in ResourceModel().data:
        ResourceModel().data[resource_id].update(updated_data)
        return {'status': 'success'}
    else:
        return {'status': 'error', 'message': 'Resource not found.'}

@app.route('/delete/<int:resource_id>', methods=['DELETE'])
def delete_resource(resource_id):
    if resource_id in ResourceModel().data:
        del ResourceModel().data[resource_id]
        return {'status': 'success'}
    else:
        return {'status': 'error', 'message': 'Resource not found.'}

# Example usage with Flask's built-in development server
if __name__ == ""__main__"":
    app.run(debug=True)
```

