0,"Create a function to read JSON from a file, parse it, calculate median for a given key, and save output to CSV. Accept command-line arguments for input file, output file, key index, and usage flag. Validate parameters, handle errors, implement caching, and offer filtering and sorting options. Write processed data to CSV and provide usage instructions when requested.",121,,"['```python
import argparse
import json
import csv
from statistics import median
import os.path
from functools import lru_cache

@lru_cache(maxsize=128)
def read_json(file):
    try:
        with open(file, ""r"") as f:
            return json.load(f)
    except FileNotFoundError:
        raise ValueError(f""File '{file}' not found."")

@lru_cache(maxsize=128)
def filter_and_sort(data, key, ascending=True):
    return sorted([val[key] for val in data], key=lambda x: x if ascending else lambda x: -x)

def calculate_median(lst):
    n = len(lst)
    if n % 2 == 0:
        return (sum(lst[n//2-1:n//2]) / 2)
    else:
        return lst[(n - 1) // 2]

def save_to_csv(output, key, data):
    with open(output, ""w"", newline="""") as csvfile:
        fieldnames = [key, ""__mean"", ""__median""]
        writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
        writer.writeheader()
        for item in data:
            writer.writerow({key: item[key], ""__mean"": round(sum(data[key])/len(data), 2), ""__median"": calculate_median([val[key] for val in data])})

def parse_arguments():
    parser = argparse.ArgumentParser()
    parser.add_argument(""input"", help=""Input JSON file"")
    parser.add_argument(""output"", help=""Output CSV file"")
    parser.add_argument(""-k"", ""--key"", help=""Key to calculate median (default: first key)"", type=int)
    parser.add_argument(""-f"", ""--filter"", help=""Filter items by value in the given key"", action=""store_true"")
    parser.add_argument(""-s"", ""--sort"", help=""Sort items by the given key"", action=""store_true"")
    parser.add_argument(""-a"", ""--ascending"", help=""Ascending order for --sort (default: True)"", action=""store_false"", dest=""sort"")
    parser.add_argument(""-h"", ""--help"", help=parser.get_usage(), action=""store_true"")
    args = parser.parse_args()

    if args.help:
        print(__doc__)
        return

    key = args.key if args.key is not None else 0
    filtering = args.filter
    sorting = args.sort
    ascending = args.ascending

    return (args.input, args.output, key, filtering, sorting, ascending)

def main():
    input_file, output_file, key, filtering, sorting, ascending = parse_arguments()

    data = read_json(input_file)
    if filtering:
        data = {val: k for k, val in sorted(data.items(), key=lambda x: x[1]) if x[1][key] >= filter_and_sort([val[key] for val in data], key)[-1]}
    if sorting:
        data = {k: v for k, v in sorted(data.items(), key=lambda x: x[1][key], reverse=not ascending)}

    median = calculate_median([val[key] for val in data.values()])
    save_to_csv(output_file, key, data)
    print(f""Calculated median: {median}"")

