Create an instance of `UserSessionManager`, generate multiple session IDs for testing purposes, log in several users across different sessions, log out some users from specific sessions, then print out details like total active users and average session age.",338,,"['```python
import datetime
from typing import List, Optional, Dict
from dataclasses import Dataclass

class Session:
    def __init__(self):
        self.created_at = datetime.date.today()
        self.users: Dict[str, str] = {}

class UserSessionManager:
    MAX_SESSIONS = 5

    def __init__(self):
        self.sessions: List[Session] = []
        self._generate_sessions()

    def _generate_sessions(self):
        for _ in range(self.MAX_SESSIONS):
            session = Session()
            self.sessions.append(session)

    def create_session(self) -> Optional[int]:
        if not self.sessions:
            return None
        else:
            last_session = self.sessions[-1]
            self.sessions.pop()
            return last_session.users, last_session.created_at

    def register(self, user_id: str, session_id: int):
        if 0 <= session_id < len(self.sessions):
            self.sessions[session_id].users[user_id] = f""{datetime.date.today()}""
            return True
        else:
            return False

    def logout(self, user_id: str):
        for session in self.sessions:
            if user_id in session.users:
                session.users.pop(user_id)

    def get_active_users(self) -> List[str]:
        active_users = []
        for session in self.sessions:
            active_users += list(session.users.values())
        return active_users

    def session_age(self, session_id: int) -> datetime.timedelta:
        if 0 <= session_id < len(self.sessions):
            today = datetime.date.today()
            created_at = self.sessions[session_id].created_at
            return today - created_at
        else:
            return None

    def total_active_users(self) -> int:
        return len([user for session in self.sessions for user in session.users.values()])

    def average_session_age(self) -> datetime.timedelta:
        active_count = self.total_active_users()
        total_age = sum([self.session_age(session_id) for session_id, _ in enumerate(self.sessions) if self.session_age(session_id)])
        return total_age / active_count if active_count > 0 else datetime.timedelta(0)

# Example usage:
mgr = UserSessionManager()
user1, session1 = mgr.create_session()
mgr.register(""u1"", session1)
mgr.register(""u2"", session1)
mgr.register(""u3"", mgr.create_session()[0])
print(f""Total active users: {mgr.total_active_users()}"")
print(f""Average session age: {mgr.average_session_age()}"")
mgr.logout(""u1"")
print(f""Total active users after logout: {mgr.total_active_users()}"")
```']",0,[0],[],True,0,0,0,

