from rest_framework import viewsets, status
from rest_framework.response import Response
from elasticsearch import Elasticsearch
from django.apps import AppConfig
from yourappname.models import YourModelName  # Replace with actual model name
from yourappname.serializers import YourModelSerializer  # Replace with actual serializer name

class YourModelViewSet(viewsets.ModelViewSet):
    queryset = YourModelName.objects.all()
    serializer_class = YourModelSerializer

    def get_es_client(self):
        app_config = AppConfig.get_app_config('yourappname')  # Replace with actual app name
        es_host = app_config.ES_HOST
        es = Elasticsearch([{'host': es_host, 'port': 9200}])
        return es

    def create(self, request, *args, **kwargs):
        serialized_data = self.serializer_class(data=request.data).validate()
        es = self.get_es_client()
        try:
            es.index(index='your_elasticsearch_index', body=serialized_data)  # Replace with actual index name
            return Response({""message"": ""Document created successfully""}, status=status.HTTP_201_CREATED)
        except Exception as e:
            return Response({""error"": str(e)}, status=status.HTTP_500_INTERNAL_SERVER_ERROR)

    def retrieve(self, request, *args, **kwargs):
        es = self.get_es_client()
        try:
            query_params = request.query_params
            results = es.search(index='your_elasticsearch_index', body={""query"": {""query_string"": query_params[""q""]}})  # Replace with actual index name and handle query parameters
            serialized_results = self.serializer_class(results['hits']['hits'], many=True)
            return Response(serialized_results.data, status=status.HTTP_200_OK)
        except Exception as e:
            return Response({""error"": str(e)}, status=status.HTTP_500_INTERNAL_SERVER_ERROR)
```

