# FileOperations.py
from typing import List, Tuple, Union
import json
import csv
import os

class FileOperations:
    def __init__(self, save_to_json=False):
        self._filePath = None
        self._rowCount = 0
        self._columnCount = 0
        self._data = []
        self._save_to_json = save_to_json

    @property
    def filePath(self) -> str:
        return self._filePath

    @property
    def rowCount(self) -> int:
        return self._rowCount

    @property
    def columnCount(self) -> int:
        return self._columnCount

    def ReadCSV(self, filePath: str):
        self._filePath = filePath
        with open(filePath, 'r') as csvFile:
            reader = csv.reader(csvFile)
            self._rowCount = sum(1 for row in reader)
            self._columnCount = next(reader)[::-1][0] + 1
            self._data = list(reader)
        if self._save_to_json:
            with open(filePath.replace("".csv"", "".json""), 'w') as jsonFile:
                json.dump(self._data, jsonFile)

    def WriteCSV(self):
        with open(self._filePath, 'w', newline='') as csvFile:
            writer = csv.writer(csvFile)
            for row in self._data:
                writer.writerow(row)

    def UpdateRow(self, index: int, row: List[Union[int, str]]):
        if index < 0 or index >= self._rowCount:
            raise IndexError(""Invalid row index"")
        self._data[index] = row

    def InsertRow(self, index: int, row: List[Union[int, str]]):
        if index < 0 or index > self._rowCount:
            raise IndexError(""Invalid row index"")
        self._data.insert(index, row)
        self._rowCount += 1

    def DeleteRow(self, index: int):
        if index < 0 or index >= self._rowCount:
            raise IndexError(""Invalid row index"")
        del self._data[index]
        self._rowCount -= 1

    def FilterRowsByCriteria(self, criteria):
        pass # Implement your filtering logic here

    def SortRowsByColumn(self, columnIndex: int):
        self._data.sort(key=lambda row: row[columnIndex])

