from Crypto.Util.Padding import pad

class EnhancedEncryptionService:
    def generate_dns_query(self, domain_name: str, ip_address: str, protocol_type: str) -> str:
        return f""DNS/{domain_name}/{ip_address}/{protocol_type}""

    def encrypt_data(self, data: bytes) -> bytes:
        cipher = DES3.new(b'abcdefgh', DES3.MODE_CFB, iv=b'01234567')
        return cipher.encrypt(pad(data.encode(), DES3.block_size))

    def validate_token_response(self, response_dict: dict) -> bool:
        if not all(key in response_dict for key in ('access_token', 'expires_in', 'token_type')):
            return False

        if response_dict['token_type'] != 'Bearer':
            return False

        if not isinstance(response_dict['expires_in'], int) or response_dict['expires_in'] <= 0:
            return False

        return True

    def compute_md5_hash(self, base64_data: str) -> str:
        data = b64decode(base64_data)
        hash_object = hashlib.md5()
        hash_object.update(data)
        return hash_object.hexdigest()
